function Face({color,expression='idle',small=false}:{color:string,expression?:string,small?:boolean}){const persona=bots.find(b=>b.color===color)?.name||'JARVIS';return <FaceArt persona={persona} state={expression} className={'face '+expression+(small?' small':'')} fallback={<svg className={'face '+expression+(small?' small':'')} viewBox="0 0 100 100" aria-label={expression+' face'} role="img"><circle cx="50" cy="50" r="43" fill={color}/><path d="M18 32Q24 4 68 12L80 28Q62 23 46 25L24 32Z" fill="#24242a"/><path d="M27 38Q35 32 42 38M59 38Q68 32 76 38" stroke="#292930" strokeWidth="4" fill="none" strokeLinecap="round"/><ellipse cx="35" cy="47" rx="10" ry={expression==='thinking'?7:9} fill="#fff8ef"/><ellipse cx="65" cy="47" rx="10" ry="9" fill="#fff8ef"/><circle cx={expression==='thinking'?38:35} cy="47" r="5" fill="#202027"/><circle cx={expression==='thinking'?68:65} cy="47" r="5" fill="#202027"/><circle cx="33" cy="45" r="1.5" fill="white"/><circle cx="63" cy="45" r="1.5" fill="white"/><ellipse cx="24" cy="60" rx="7" ry="3" fill="#ffe5d0" opacity=".5"/><ellipse cx="76" cy="60" rx="7" ry="3" fill="#ffe5d0" opacity=".5"/>{expression==='speaking'?<ellipse className="mouth" cx="50" cy="69" rx="9" ry="10" fill="#272730"/>:<path d="M39 66Q50 75 61 66" fill="none" stroke="#272730" strokeWidth="4" strokeLinecap="round"/>}</svg>}/> }
type Turn={name:string,text:string};
